public static AVAUnblockProdTableWorkController construct(SysOperationExecutionMode _mode = SysOperationExecutionMode::Synchronous)
{
    AVAUnblockProdTableWorkController controller = new AVAUnblockProdTableWorkController(classStr(AVAUnblockProdTableWorkService), methodStr(AVAUnblockProdTableWorkService, unblock),_mode);
    return controller;
}

public void new(IdentifierName _className = classStr(AVAUnblockProdTableWorkService) , IdentifierName _methodName =  methodStr(AVAUnblockProdTableWorkService, unblock), SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

private static void main(Args _args)
{
    AVAUnblockProdTableWorkController controller;

    controller = AVAUnblockProdTableWorkController::construct();
    controller.parmArgs(_args);
    controller.initializeContractFromArgs(_args);
    controller.parmShowDialog(false);
    controller.parmLoadFromSysLastValue(false);
    controller.startOperation();
}

protected void initializeContractFromArgs(Args _args)
{
    AVAUnblockProdTableWorkContract  unblockProdTableWorkContract;

    if (_args.record())
    {
        unblockProdTableWorkContract = this.getDataContractObject();

        unblockProdTableWorkContract.initFromArgs(_args);
        unblockProdTableWorkContract.parmInitFromRecord(true);
    }
}

protected void afterOperation(SysOperationExecutionMode _executionMode, AifAsyncResult _asyncResult)
{
    Object          callerObject;
    FormObjectSet   formObjectSet;

    super(_executionMode, _asyncResult);

    if (this.parmArgs()
     && this.parmArgs().record()
     && this.parmArgs().caller())
    {
        callerObject = this.parmArgs().caller();

        if (formHasMethod(callerObject, identifierStr(avaResearchForm)))
        {
            callerObject.avaResearchForm();
        }

        if (this.parmArgs().record().dataSource())
        {
            formObjectSet = this.parmArgs().record().dataSource();
            formObjectSet.research(true);
        }
    }
}
